//#region src/api/client.ts
var baseURL = localStorage.getItem("api_url") || "http://localhost:8000";
async function listUsers() {
	return (await axios.get(`${baseURL}/auth/users`, { headers: getAuthHeaders() })).data;
}
async function registerUser(data) {
	return (await axios.post(`${baseURL}/auth/register`, data, { headers: getAuthHeaders() })).data;
}
async function updateUser(userId, data) {
	return (await axios.patch(`${baseURL}/auth/users/${userId}`, data, { headers: getAuthHeaders() })).data;
}
async function deleteUser(userId) {
	await axios.delete(`${baseURL}/auth/users/${userId}`, { headers: getAuthHeaders() });
}
var getAuthHeaders = () => {
	const token = typeof window !== "undefined" ? localStorage.getItem("authToken") : null;
	return token ? { Authorization: `Bearer ${token}` } : {};
};
async function searchRapports(req) {
	return (await axios.post(`${baseURL}/search`, req, {
		timeout: 3e4,
		headers: getAuthHeaders()
	})).data;
}
async function listParts(params) {
	return (await axios.get(`${baseURL}/parts`, {
		timeout: 3e4,
		headers: getAuthHeaders(),
		params
	})).data;
}
async function processConstat(file) {
	const formData = new FormData();
	formData.append("file", file);
	const res = await axios.post(`${baseURL}/process-constat`, formData, {
		timeout: 3e5,
		headers: getAuthHeaders()
	});
	console.log("RAW RESPONSE:", JSON.stringify(res.data, null, 2));
	return res.data;
}
async function extractFieldsWithGroq(fullText) {
	const res = await axios.post(`${baseURL}/extract-fields`, { text: fullText }, { timeout: 3e4 });
	console.log("Extracted fields:", JSON.stringify(res.data, null, 2));
	return res.data;
}
async function analyzeConstat(fullText) {
	return (await axios.post(`${baseURL}/analyze-constat`, { full_text: fullText }, { timeout: 9e4 })).data;
}
async function saveConstatReport(constatId, report) {
	return (await axios.put(`${baseURL}/constats/${constatId}/report`, report, { headers: getAuthHeaders() })).data;
}
async function loginUser(email, password) {
	const body = new URLSearchParams();
	body.append("username", email);
	body.append("password", password);
	return (await axios.post(`${baseURL}/auth/login`, body, {
		headers: { "Content-Type": "application/x-www-form-urlencoded" },
		timeout: 1e4
	})).data;
}
async function getCurrentUser() {
	return (await axios.get(`${baseURL}/auth/me`, { headers: getAuthHeaders() })).data;
}
async function saveConstat(data) {
	return (await axios.post(`${baseURL}/constats/`, data, { headers: getAuthHeaders() })).data;
}
async function listConstats() {
	return (await axios.get(`${baseURL}/constats/`, { headers: getAuthHeaders() })).data;
}
